import {navigationColor,navigationLegend} from './navigation-map.js?v=live-scenario-comparisons-2';
import {escapeAnnouncement} from './scenario-announcements.js?v=live-scenario-comparisons-2';
export const SCENARIO_PREVIEW_LAYERS={city:'Starting city',power:'Power service',water:'Water service',rail:'Surface rail'};
export function scenarioPreviewMap(city,layer='city'){
 if(!Object.hasOwn(SCENARIO_PREVIEW_LAYERS,layer))throw Error('Unknown scenario preview layer.');
 const paths=new Map(),size=city.size;
 for(let y=0;y<size;y++)for(let x=0;x<size;){const color=navigationColor(city.tiles[y*size+x],layer),start=x;while(++x<size&&navigationColor(city.tiles[y*size+x],layer)===color){}const length=x-start;paths.set(color,(paths.get(color)||'')+`M${start} ${y}h${length}v1h-${length}z`);}
 return `<svg viewBox="0 0 ${size} ${size}" role="img" aria-label="${escapeAnnouncement(city.name)}: ${SCENARIO_PREVIEW_LAYERS[layer]} preview" style="display:block;width:100%;max-width:260px;aspect-ratio:1;border:1px solid #58716b;border-radius:6px;image-rendering:pixelated" shape-rendering="crispEdges">${[...paths].map(([color,path])=>`<path fill="${color}" d="${path}"/>`).join('')}</svg>`;
}
export function scenarioPreviewPanel(city){return `<section aria-label="Starting city preview"><h3>Inspect the starting town</h3><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:20px;align-items:start"><div id="scenarioPreviewMap">${scenarioPreviewMap(city)}</div><div><p>${city.size} × ${city.size} tiles · January ${city.startYear} · ${city.stats.population.toLocaleString('en-US')} residents · §${Math.round(city.funds).toLocaleString('en-US')}</p><label>Preview layer<select id="scenarioPreviewLayer">${Object.entries(SCENARIO_PREVIEW_LAYERS).map(([key,name])=>`<option value="${key}">${name}</option>`).join('')}</select></label><p id="scenarioPreviewLegend" class="fine">${navigationLegend('city')} · Top-down view; orientation matches the unrotated city.</p><p class="fine">This is the prepared starting town. Inspecting it does not change your current city.</p></div></div></section>`;}
export function installScenarioPreview(city,root=document){const select=root.querySelector('#scenarioPreviewLayer');select.onchange=()=>{root.querySelector('#scenarioPreviewMap').innerHTML=scenarioPreviewMap(city,select.value);root.querySelector('#scenarioPreviewLegend').textContent=navigationLegend(select.value)+' · Top-down view; orientation matches the unrotated city.';};}
